 "content": "def transform(grid):
    """Compare aligned cells in panels on either side of a full-height divider."""
    h, w = len(grid), len(grid[0])
    separators = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    if not separators:
        raise ValueError('vertical separator not found')
    # The actual divider is the central uniform column; uniform field columns
    # may occur inside the panels as distractors.
    sep = max(separators, key=lambda c: min(c, w - c - 1))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    width = min(len(left[0]), len(right[0]))
    left_colors = {v for row in left for v in row[:width]}
    right_colors = {v for row in right for v in row[:width]}
    shared = left_colors & right_colors
    if len(shared) != 1:
        raise ValueError(f'expected one shared panel color, found {shared}')
    marker = next(iter(shared))
    return [[3 if left[r][c] == marker and right[r][c] == marker else 5
             for c in range(width)] for r in range(h)]

